80	+const DEFAULT_APP = '/app';
81	+const APP = existsSync(DEFAULT_APP) ? DEFAULT_APP : (process.env.SR5_APP_ROOT || DEFAULT_APP);
82	+const DEFAULT_REPORT_DIR = '/logs/verifier';
83	+const REPORT_DIR = existsSync(DEFAULT_APP)
84	+    ? DEFAULT_REPORT_DIR
85	+    : (process.env.SR5_REPORT_DIR || DEFAULT_REPORT_DIR);
86	+const REPORT = path.join(REPORT_DIR, 'report.xml');
87	+const SUITE = 'modifiable_value_linked_decimal';
88	+
89	+const CASE_NAMES = [
90	+    // f2p
91	+    'ap_value_field_survives_fractional_input_unrounded',
92	+    'ap_base_field_survives_fractional_input_unrounded',
93	+    'linked_ap_schemafield_cleans_fractional_damage_ap_payload_intact',
94	+    'modifiable_value_total_rounds_up_not_truncated',
95	+    'modifiable_value_changes_apply_in_priority_order',
96	+    'reduce_damage_by_hits_does_not_mutate_original',
97	+    // p2p
98	+    'unrelated_value_field_bare_call_still_rounds_to_integer',
99	+    'value_max_pair_sibling_factory_still_integer_only',
100	+    'change_entry_numeric_fields_still_integer_only',
101	+    'threshold_bare_base_value_pair_call_still_integer_only',
102	+    'modifiable_value_min_max_enforcement_still_applies',
103	+    'modifiable_value_same_mode_changes_still_accumulate',
104	+    'modify_damage_by_hits_raising_path_still_adds_correctly',
105	+];
106	+
107	+const results = [];
108	+function record(name, passed, msg = '') {
109	+    results.push({ name, passed, msg });
110	+}
111	+function safe(name, fn) {
112	+    try {
113	+        fn();
114	+    } catch (e) {
115	+        record(name, false, `unexpected error: ${e && e.stack ? e.stack : e}`);
116	+    }
117	+}
118	+
119	+// -- Generic auto-stub for modules we do not model -----------------------------
120	+// apply() returns {} (not bare undefined): a real-loaded file that object-spreads an
121	+// auto-stubbed call's return value must not crash.
122	+function autoStub(label) {
123	+    const cache = new Map();
124	+    const fn = function () {};
125	+    return new Proxy(fn, {
126	+        get(_t, prop) {
127	+            if (prop === '__esModule') return true;
128	+            if (prop === Symbol.toPrimitive) return () => `[stub ${label}]`;
129	+            if (prop === 'toString') return () => `[stub ${label}]`;
130	+            if (prop === 'then') return undefined;
131	+            if (typeof prop === 'symbol') return undefined;
132	+            if (!cache.has(prop)) cache.set(prop, autoStub(`${label}.${String(prop)}`));
133	+            return cache.get(prop);
134	+        },
135	+        set() {
136	+            return true;
137	+        },
138	+        has() {
139	+            return true;
140	+        },
141	+        apply() {
142	+            return {};
143	+        },
144	+        construct() {
145	+            return {};
146	+        },
147	+    });
148	+}
149	+
150	+// -- Minimal, faithful-enough foundry.data.fields.DataField family ------------
151	+// Only clean() is modeled -- the part of Foundry's schema-field pipeline that decides whether a
152	+// fractional NumberField value survives a document update. An integer-constrained NumberField
153	+// ROUNDS a fractional input rather than rejecting it outright, which is exactly why a 0.5 AP
154	+// silently became 0/1 with no validation error shown to the user.
155	+class DataField {
156	+    constructor(options = {}) {
157	+        this.options = options || {};
158	+    }
159	+    getInitialValue() {
160	+        return 'initial' in this.options ? this.options.initial : undefined;
161	+    }
162	+    clean(value) {
163	+        if (value === undefined) return this.getInitialValue();
164	+        return value;
165	+    }
166	+}
167	+class StringField extends DataField {
168	+    getInitialValue() {
169	+        if ('initial' in this.options) return this.options.initial;
170	+        return this.options.required && !this.options.nullable ? '' : undefined;
171	+    }
172	+}
173	+class BooleanField extends DataField {
174	+    getInitialValue() {
175	+        return 'initial' in this.options ? this.options.initial : false;
176	+    }
177	+}
178	+class DocumentUUIDField extends DataField {}
179	+class NumberField extends DataField {
180	+    clean(value) {
181	+        if (value === undefined) return this.getInitialValue();
182	+        let v = typeof value === 'string' ? Number(value) : value;
183	+        if (typeof v === 'number' && Number.isFinite(v) && this.options.integer) v = Math.round(v);
184	+        return v;
185	+    }
186	+}
187	+class ArrayField extends DataField {
188	+    constructor(element, options = {}) {
189	+        super(options);
190	+        this.element = element;
191	+    }
192	+    getInitialValue() {
193	+        return 'initial' in this.options ? this.options.initial : [];
194	+    }
195	+    clean(value) {
196	+        const arr = Array.isArray(value) ? value : this.getInitialValue();
197	+        return arr.map((v) => (this.element && typeof this.element.clean === 'function' ? this.element.clean(v) : v));
198	+    }
199	+}
200	+class SchemaField extends DataField {
201	+    constructor(fields, options = {}) {
202	+        super(options);
203	+        this.fields = fields || {};
204	+    }
205	+    getInitialValue() {
206	+        const out = {};
207	+        for (const [k, f] of Object.entries(this.fields)) out[k] = f && typeof f.getInitialValue === 'function' ? f.getInitialValue() : undefined;
208	+        return out;
209	+    }
210	+    clean(value) {
211	+        const src = value && typeof value === 'object' ? value : {};
212	+        const out = {};
213	+        for (const [k, f] of Object.entries(this.fields)) {
214	+            out[k] = f && typeof f.clean === 'function' ? f.clean(src[k]) : src[k];
215	+        }
216	+        return out;
217	+    }
218	+}
219	+
220	+globalThis.foundry = {
